import React from 'react'
import { Link } from 'react-router-dom'

const cards = [
  { to: '/', icon: 'fa-desktop', label: 'Dashboard' },
  { to: '/employees', icon: 'fa-users', label: 'Employees' },
  { to: '/add-employee/_add', icon: 'fa-user-plus', label: 'Add Employee' },
  { to: '/view-leaves', icon: 'fa-calendar', label: 'View Leaves' }
]

function AdminDashboard() {
  const now = new Date()
  const time = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })

  return (
    <div style={{ minHeight: '100vh', background: '#000', color: '#fff', padding: 30, fontFamily: 'sans-serif' }}>
      <h2 style={{ marginBottom: 5 }}>Welcome, Admin</h2>
      <p style={{ opacity: 0.7, marginBottom: 30 }}>{time}</p>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(180px,1fr))', gap: 20 }}>
        {cards.map(c => (
          <Link key={c.to} to={c.to} style={{ textDecoration: 'none', color: '#fff' }}>
            <div style={{ border: '1px solid #fff', padding: 25, borderRadius: 10, textAlign: 'center', transition: '0.3s' }}>
              <i className={`fa ${c.icon}`} style={{ fontSize: 24, marginBottom: 10 }}></i>
              <div>{c.label}</div>
            </div>
          </Link>
        ))}
      </div>
    </div>
  )
}

export default AdminDashboard
